#[derive(Debug,PartialEq)] pub enum AssignmentResourceErrorV2 { Policy,Budget }
pub struct AssignmentWorkScheduleV2 {
    pub version: u16,
    pub revision: u16,
    pub per_codec_step: u64,
    pub per_hash_byte: u64,
    pub per_signature: u64,
    pub per_element: u64,
    pub per_term: u64,
    pub per_io_byte: u64,
    pub per_control: u64,
}
pub struct AssignmentWorkQuantitiesV2 {
    pub codec_steps: u64,
    pub hash_bytes: u64,
    pub signatures: u64,
    pub elements: u64,
    pub terms: u64,
    pub io_bytes: u64,
    pub controls: u64,
}
fn finite(values: &[u64]) -> bool {
    values.iter().all(|n| *n > 0 && *n < u64::MAX)
}
impl AssignmentWorkScheduleV2 {
pub fn validate(&self) -> Result<(), AssignmentResourceErrorV2> {
        if self.version != 2
            || self.revision != 1
            || !finite(&[
                self.per_codec_step,
                self.per_hash_byte,
                self.per_signature,
                self.per_element,
                self.per_term,
                self.per_io_byte,
                self.per_control,
            ])
        {
            return Err(AssignmentResourceErrorV2::Policy);
        }
        Ok(())
    }
pub fn charge(&self, q: AssignmentWorkQuantitiesV2) -> Result<u64, AssignmentResourceErrorV2> {
        self.validate()?;
        [
            (self.per_codec_step, q.codec_steps),
            (self.per_hash_byte, q.hash_bytes),
            (self.per_signature, q.signatures),
            (self.per_element, q.elements),
            (self.per_term, q.terms),
            (self.per_io_byte, q.io_bytes),
            (self.per_control, q.controls),
        ]
        .into_iter()
        .try_fold(0u64, |total, (rate, amount)| {
            amount.checked_mul(rate).and_then(|n| total.checked_add(n)).ok_or(AssignmentResourceErrorV2::Budget)
        })
    }
pub fn source_preparation_read_work_v2(&self, body_bytes: u64) -> Result<u64, AssignmentResourceErrorV2> {
        let authenticated_bytes = body_bytes.checked_add(32 * 128).ok_or(AssignmentResourceErrorV2::Budget)?;
        self.charge(AssignmentWorkQuantitiesV2 {
            codec_steps: authenticated_bytes,
            hash_bytes: authenticated_bytes,
            signatures: 0,
            elements: 0,
            terms: 0,
            io_bytes: body_bytes,
            controls: 1,
        })
    }
}
#[test]
fn source_preparation_covers_both_children_at_every_u32_merkle_level() {
    let schedule = AssignmentWorkScheduleV2 {
        version: 2, revision: 1,
        per_codec_step: 2, per_hash_byte: 3, per_signature: 5,
        per_element: 7, per_term: 11, per_io_byte: 13, per_control: 17,
    };
    for leaves in [1u32, 2, 3, 4, 255, 65_535, u32::MAX] {
        let mut width = u64::from(leaves);
        let mut levels = 0u128;
        while width > 1 {
            width = width.div_ceil(2);
            levels += 1;
        }
        for body_bytes in [64u64, 512, 65_536] {
            // Independent lower bound: encoded-body codec + body hash,
            // two 64-byte children at each branch, actual read and control.
            // Odd promotion can require fewer hashes; a full path is bounded.
            let minimum = 2u128 * u128::from(body_bytes)
                + 3 * (u128::from(body_bytes) + 128 * levels)
                + 13 * u128::from(body_bytes) + 17;
            let quoted = schedule.source_preparation_read_work_v2(body_bytes).unwrap();
            assert!(u128::from(quoted) >= minimum, "{leaves} leaves, {body_bytes} body bytes");
        }
    }
    assert_eq!(schedule.source_preparation_read_work_v2(u64::MAX), Err(AssignmentResourceErrorV2::Budget));
    assert_eq!(schedule.source_preparation_read_work_v2(u64::MAX - 4096), Err(AssignmentResourceErrorV2::Budget));
    let mut invalid = schedule;
    invalid.per_hash_byte = 0;
    assert_eq!(invalid.source_preparation_read_work_v2(512), Err(AssignmentResourceErrorV2::Policy));
}
